using namespace std;

struct Vec {
    double x, y;
    Vec(double x = 0, double y = 0) : x(x), y(y) {}
    Vec operator*(double k) const { return Vec(x * k, y * k); }
    double len() const { return sqrt(x * x + y * y); }
    Vec unit() const {
        double l = len();
        if (l == 0) return Vec(0, 0);
        return Vec(x / l, y / l);
    }
    void print() const { cout << "(" << x << ", " << y << ")"; }
};

Vec operator*(double k, const Vec& v) {
    return Vec(v.x * k, v.y * k);
}

int main() {
    Vec a(3, 4);

    Vec doubled = a * 2;
    Vec reversed = a * (-1);
    Vec halved = a * 0.5;
    Vec u = a.unit();

    cout << "a = "; a.print(); cout << ", |a| = " << a.len() << endl;
    cout << "2a = "; doubled.print(); cout << ", |2a| = " << doubled.len() << endl;
    cout << "-a = "; reversed.print(); cout << ", |-a| = " << reversed.len() << endl;
    cout << "0.5a = "; halved.print(); cout << ", |0.5a| = " << halved.len() << endl;
    cout << "单位向量 = "; u.print(); cout << ", |u| = " << u.len() << endl;

    return 0;
}

