#include <iostream>
#include <cmath>
using namespace std;

const double PI = acos(-1.0);

struct Vec {
    double x, y;
    Vec(double x = 0, double y = 0) : x(x), y(y) {}
    double dot(const Vec& b) const { return x * b.x + y * b.y; }
    double len() const { return sqrt(x * x + y * y); }
};

double angleBetween(Vec a, Vec b) {
    double la = a.len(), lb = b.len();
    if (la == 0 || lb == 0) return 0;
    double cosTheta = a.dot(b) / (la * lb);
    if (cosTheta > 1) cosTheta = 1;
    if (cosTheta < -1) cosTheta = -1;
    return acos(cosTheta);
}

int main() {
    Vec a(1, 0);
    Vec b(0, 1);
    Vec c(1, 1);

    cout << "(1,0) 与 (0,1) 的夹角: " << angleBetween(a, b) / PI * 180 << " 度" << endl;
    cout << "(1,0) 与 (1,1) 的夹角: " << angleBetween(a, c) / PI * 180 << " 度" << endl;
    cout << "(1,0) 与 (-1,0) 的夹角: " << angleBetween(a, Vec(-1, 0)) / PI * 180 << " 度" << endl;

    Vec d(3, 4), e(4, -3);
    cout << "(3,4)·(4,-3) = " << d.dot(e) << " => ";
    if (d.dot(e) == 0) cout << "垂直" << endl;

    return 0;
}

#include <iostream>
#include <cmath>
using namespace std;

struct Line {
    double A, B, C;
    Line(double A, double B, double C) : A(A), B(B), C(C) {}
    static Line fromTwoPoints(double x1, double y1, double x2, double y2) {
        return Line(y1 - y2, x2 - x1, x1 * y2 - x2 * y1);
    }
    static Line fromPointSlope(double x0, double y0, double k) {
        return Line(k, -1, y0 - k * x0);
    }
    bool contains(double x, double y) const {
        return fabs(A * x + B * y + C) < 1e-9;
    }
    double slope() const {
        if (fabs(B) < 1e-9) return 1e18;
        return -A / B;
    }
};

int main() {
    Line l1 = Line::fromTwoPoints(1, 2, 3, 6);
    cout << "过 (1,2) 和 (3,6) 的直线: " << l1.A << "x + " << l1.B << "y + " << l1.C << " = 0" << endl;
    cout << "斜率: " << l1.slope() << endl;
    cout << "(2,4) 在直线上? " << (l1.contains(2, 4) ? "是" : "否") << endl;
    cout << "(0,0) 在直线上? " << (l1.contains(0, 0) ? "是" : "否") << endl;

    Line l2 = Line::fromPointSlope(1, 1, 2);
    cout << "过 (1,1) 斜率 2 的直线: " << l2.A << "x + " << l2.B << "y + " << l2.C << " = 0" << endl;

    return 0;
}

