    double x4 = 4, y4 = 6;
    double x5 = 5, y5 = 5;

    double d1 = distance2(x1, y1, x3, y3);
    double d2 = distance2(x1, y1, x5, y5);
    cout << "A 到 C 更近" << (d1 < d2 ? "是" : "否") << endl;

    double x0 = 0, y0 = 0;
    double radius = 5.0;
