    Point p1(0, 0), p2(4, 0), p3(0, 3);
    cout << "三角形面积: " << triangleArea(p1, p2, p3) << endl;

    Point o(0, 0), x(1, 0), y1(1, 1), y2(1, -1);
    cout << "(1,1) 在 x 轴的: " << (direction(o, x, y1) > 0 ? "左侧" : "右侧") << endl;
